meta.script:
 document.addEventListener('DOMContentLoaded', function () {
    var createfeedform = document.getElementById('createfeed');
    // Index page.
    if (createfeedform) {
        createfeedform.addEventListener('submit', function(e) {
            var elms = this.elements;
            if (!elms.key.value  !elms.url.value) {
                alert("Please enter both an access key and the feed URL.");
                e.preventDefault();
            } else if (!elms.key.value) {
                alert("Please enter an access key. If you don’t have an access key, please contact me.");
                e.preventDefault();
            } else if (!elms.url.value) {
                alert("Please enter a feed URL.");
                e.preventDefault();
            } else {
                elms.backfeedit.disabled = true;
                elms.backfeedit.value = 'Please wait…';
                setTimeout(function () {elms.backfeedit.value = 'A small feed takes minutes…';}, 2e3);
                setTimeout(function () {elms.backfeedit.value = 'A large feed takes about an hour…';}, 6e3);
                setTimeout(function () {elms.backfeedit.value = 'If the page dies, try again later…';}, 10e3);
                setTimeout(function () {elms.backfeedit.value = 'It’s only slow the first time…';}, 14e3);
                setTimeout(function () {elms.backfeedit.value = 'Let it process complete before trying again…';}, 17e3);
                setTimeout(function () {elms.backfeedit.value = 'Just a little longer…';}, 21e3);
                setTimeout(function () {elms.backfeedit.value = 'Patiently waiting…';}, 23e3);
                setTimeout(function () {elms.backfeedit.value = 'Still crunching…';}, 25e3);
                setTimeout(function () {elms.backfeedit.value = 'Really, any minute now…';}, 28e3);
                setTimeout(function () {elms.backfeedit.value = 'Almost done…';}, 31e3);
                setTimeout(function () {elms.backfeedit.value = 'Almost done (just kidding)…';}, 34e3);
                setTimeout(function () {elms.backfeedit.value = 'Go make some coffee…';}, 37e3);
                setTimeout(function () {elms.backfeedit.value = 'This really might take awhile…';}, 40e3);
                setTimeout(function () {elms.backfeedit.value = 'Please wait…';}, 46e3);
                setTimeout(function () {
                    elms.backfeedit.disabled = false;
                    elms.backfeedit.value = 'Backfeed it!';
                }, 90000);
                return (typeof submitted == 'undefined') ? (submitted = true) : !submitted;
            }
        });
    }
});
